begin;
-- Retain the existing posts/admin_users and their contents.
create or replace function public.is_site_admin() returns boolean language sql stable security invoker set search_path='' as $$ select exists(select 1 from public.admin_users where user_id=(select auth.uid())); $$;
revoke all on function public.is_site_admin() from public;
grant execute on function public.is_site_admin() to anon,authenticated;
grant select on public.admin_users to authenticated;
grant select(user_id) on public.admin_users to anon;
alter table public.posts add column if not exists title_bn text;
alter table public.posts add column if not exists excerpt_bn text;
alter table public.posts add column if not exists content_bn text;
alter table public.posts add column if not exists category text not null default 'Operations';
alter table public.posts add column if not exists tags text[] not null default '{}';
alter table public.posts add column if not exists featured boolean not null default false;
alter table public.posts add column if not exists comments_enabled boolean not null default true;
alter table public.posts add column if not exists seo_title text;
alter table public.posts add column if not exists seo_title_bn text;
alter table public.posts add column if not exists seo_description text;
alter table public.posts add column if not exists seo_description_bn text;
alter table public.posts add constraint posts_slug_safe check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(slug)<=120);
alter table public.posts add constraint posts_content_limits check(length(title) between 1 and 200 and length(content)<=200000 and coalesce(length(content_bn),0)<=200000);
drop policy if exists "Published posts are public" on public.posts;
create policy "Published posts are public" on public.posts for select to anon,authenticated using ((status='published' and published_at is not null and published_at<=now()) or (select public.is_site_admin()));
grant select on public.posts to anon,authenticated;
grant insert,update,delete on public.posts to authenticated;
alter table public.posts add column if not exists has_bangla boolean generated always as (title_bn is not null and content_bn is not null and length(trim(content_bn))>0) stored;
alter table public.posts add column if not exists reading_minutes integer generated always as (greatest(1,ceil(length(content)/1100.0)::integer)) stored;
alter table public.posts add column if not exists reading_minutes_bn integer generated always as (greatest(1,ceil(coalesce(length(content_bn),0)/900.0)::integer)) stored;
alter table public.posts add column if not exists search_doc tsvector generated always as (to_tsvector('simple',coalesce(title,'')||' '||coalesce(title_bn,'')||' '||coalesce(excerpt,'')||' '||coalesce(excerpt_bn,'')||' '||content||' '||coalesce(content_bn,'')||' '||category)) stored;
create index if not exists posts_search on public.posts using gin(search_doc);
create index if not exists posts_public_date on public.posts(status,published_at desc);
create index if not exists posts_tags on public.posts using gin(tags);
create table public.categories(id text primary key, name_bn text not null);
insert into public.categories values ('Operations','অপারেশনস'),('Leadership','নেতৃত্ব'),('Analytics','ডেটা বিশ্লেষণ'),('Technology','প্রযুক্তি');
alter table public.categories enable row level security;
create policy categories_read on public.categories for select to anon,authenticated using(true);
create policy categories_admin on public.categories for all to authenticated using((select public.is_site_admin())) with check((select public.is_site_admin()));
grant select on public.categories to anon,authenticated;
grant insert,update,delete on public.categories to authenticated;
create table public.comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts on delete cascade,parent_id uuid references public.comments on delete cascade,name text not null check(length(name) between 1 and 80),body text not null check(length(body) between 3 and 3000),website text check(website is null or (length(website)<=300 and website ~ '^https://')),status text not null default 'pending' check(status in ('pending','approved','rejected','spam')),created_at timestamptz not null default now());
alter table public.comments enable row level security;
create policy comments_read on public.comments for select to anon,authenticated using((status='approved' and exists(select 1 from public.posts where id=post_id and status='published' and published_at<=now())) or (select public.is_site_admin()));
create policy comments_admin on public.comments for all to authenticated using((select public.is_site_admin())) with check((select public.is_site_admin()));
grant select on public.comments to anon,authenticated;
grant insert,update,delete on public.comments to authenticated;
create index comments_post_status on public.comments(post_id,status,created_at);
create index comments_parent on public.comments(parent_id);
create schema if not exists private;
revoke all on schema private from public,anon,authenticated;
create table private.comment_contacts(comment_id uuid primary key references public.comments on delete cascade,email text not null);
alter table private.comment_contacts enable row level security;
create table private.abuse_events(id bigint generated always as identity primary key,identity_hash text not null,kind text not null,created_at timestamptz not null default now());
create index abuse_identity_date on private.abuse_events(identity_hash,created_at);
alter table private.abuse_events enable row level security;
create table private.reactions(post_id uuid references public.posts on delete cascade,visitor uuid not null,kind text not null check(kind in ('like','useful')),primary key(post_id,visitor,kind));
alter table private.reactions enable row level security;
create table public.article_stats(post_id uuid primary key references public.posts on delete cascade,likes integer not null default 0,useful integer not null default 0);
alter table public.article_stats enable row level security;
create policy stats_read on public.article_stats for select to anon,authenticated using(exists(select 1 from public.posts where id=post_id and status='published' and published_at<=now()));
grant select on public.article_stats to anon,authenticated;
create view public.journal_catalog with (security_invoker=true) as select p.*,coalesce(s.likes,0)+coalesce(s.useful,0) as appreciation from public.posts p left join public.article_stats s on s.post_id=p.id;
grant select on public.journal_catalog to anon,authenticated;
create function public.journal_tags() returns table(tag text) language sql stable security invoker set search_path='' as $$ select distinct unnest(tags) from public.posts where status='published' and published_at<=now() order by 1 $$;
revoke all on function public.journal_tags() from public;
grant execute on function public.journal_tags() to anon,authenticated;
create table public.site_content(key text primary key,value_en text not null,value_bn text not null default '',updated_at timestamptz not null default now());
alter table public.site_content enable row level security;
create policy content_read on public.site_content for select to anon,authenticated using(true);
create policy content_admin on public.site_content for all to authenticated using((select public.is_site_admin())) with check((select public.is_site_admin()));
grant select on public.site_content to anon,authenticated;
grant insert,update,delete on public.site_content to authenticated;
create table public.activity_log(id bigint generated always as identity primary key,entity text not null,action text not null,created_at timestamptz not null default now());
alter table public.activity_log enable row level security;
create policy activity_admin on public.activity_log for select to authenticated using((select public.is_site_admin()));
grant select on public.activity_log to authenticated;
create function private.log_change() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.activity_log(entity,action) values(TG_TABLE_NAME,TG_OP); return null; end $$;
revoke all on function private.log_change() from public,anon,authenticated;
create trigger posts_activity after insert or update or delete on public.posts for each row execute function private.log_change();
create trigger comments_activity after update or delete on public.comments for each row execute function private.log_change();
create function public.submit_engagement(payload jsonb,identity_hash text) returns jsonb language plpgsql security definer set search_path='' as $$
declare pid uuid; cid uuid; parent uuid; k text; n integer; begin
-- This endpoint is executable ONLY by service_role, after Edge validation.
perform pg_advisory_xact_lock(hashtextextended(identity_hash,0));
delete from private.abuse_events where created_at<now()-interval '1 day';
perform pg_advisory_xact_lock(8675309);
select count(*) into n from private.abuse_events;
if n>=2000 then raise exception 'Daily engagement limit reached'; end if;
select count(*) into n from private.abuse_events where created_at>now()-interval '1 minute';
if n>=60 then raise exception 'Busy. Please try later.'; end if;
select count(*) into n from private.abuse_events where abuse_events.identity_hash=submit_engagement.identity_hash and created_at>now()-interval '10 minutes';
if n>=8 then raise exception 'Too many requests. Try again in ten minutes.'; end if;
pid:=(payload->>'post_id')::uuid;
if not exists(select 1 from public.posts where id=pid and status='published' and published_at<=now()) then raise exception 'Article unavailable'; end if;
k:=payload->>'kind';
if k='comment' then
 select count(*) into n from private.abuse_events where kind='comment';
 if n>=200 then raise exception 'Daily comment limit reached'; end if;
 if not exists(select 1 from public.posts where id=pid and comments_enabled) then raise exception 'Comments disabled'; end if;
 if length(trim(payload->>'name')) not between 1 and 80 or length(trim(payload->>'body')) not between 3 and 3000 or length(payload->>'email')>254 or (payload->>'email') !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Invalid comment'; end if;
 parent:=nullif(payload->>'parent_id','')::uuid;
 if parent is not null and not exists(select 1 from public.comments where id=parent and post_id=pid and status='approved') then raise exception 'Reply unavailable'; end if;
 insert into public.comments(post_id,parent_id,name,body,website) values(pid,parent,trim(payload->>'name'),trim(payload->>'body'),nullif(payload->>'website','')) returning id into cid;
 insert into private.comment_contacts values(cid,lower(trim(payload->>'email')));
else
 if k not in ('like','useful') then raise exception 'Invalid reaction'; end if;
 perform pg_advisory_xact_lock(hashtextextended(pid::text,0));
 insert into private.reactions values(pid,(payload->>'visitor')::uuid,k) on conflict do nothing;
 insert into public.article_stats(post_id,likes,useful) select pid,count(*) filter(where kind='like'),count(*) filter(where kind='useful') from private.reactions where post_id=pid on conflict(post_id) do update set likes=excluded.likes,useful=excluded.useful;
end if;
insert into private.abuse_events(identity_hash,kind) values(identity_hash,k);
return jsonb_build_object('ok',true,'status',case when k='comment' then 'pending' else 'saved' end);
end $$;
revoke all on function public.submit_engagement(jsonb,text) from public,anon,authenticated;
grant execute on function public.submit_engagement(jsonb,text) to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('article-images','article-images',true,2097152,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy article_images_admin on storage.objects for all to authenticated using(bucket_id='article-images' and (select public.is_site_admin())) with check(bucket_id='article-images' and (select public.is_site_admin()) and lower(storage.extension(name)) in ('jpg','jpeg','png','webp'));
commit;
